mapper.update:
UPDATE rule_runs
SET status = #{newStatus},
    started_at = COALESCE(started_at, #{startedAt,jdbcType=TIMESTAMP,typeHandler=org.apache.ibatis.type.InstantTypeHandler}),
    finished_at = #{finishedAt,jdbcType=TIMESTAMP,typeHandler=org.apache.ibatis.type.InstantTypeHandler},
    error_message = #{errorMessage,jdbcType=VARCHAR}
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND owner_id = #{ownerId}
  AND status = #{expectedStatus}

UPDATE rule_runs
SET lease_expires_at = #{leaseExpiresAt,typeHandler=org.apache.ibatis.type.InstantTypeHandler}
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND claim_token = #{claimToken,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND execution_attempt = #{executionAttempt}
  AND status IN ('QUEUED', 'RUNNING')
  AND lease_expires_at > #{now,typeHandler=org.apache.ibatis.type.InstantTypeHandler}

UPDATE rule_runs
SET status = #{newStatus},
    started_at = COALESCE(started_at, #{startedAt,jdbcType=TIMESTAMP,typeHandler=org.apache.ibatis.type.InstantTypeHandler}),
    finished_at = #{finishedAt,jdbcType=TIMESTAMP,typeHandler=org.apache.ibatis.type.InstantTypeHandler},
    error_message = #{errorMessage,jdbcType=VARCHAR},
    lease_expires_at = CASE WHEN #{newStatus} IN ('SUCCEEDED', 'FAILED', 'CANCELLED') THEN NULL ELSE lease_expires_at END,
    claim_token = CASE WHEN #{newStatus} IN ('SUCCEEDED', 'FAILED', 'CANCELLED') THEN NULL ELSE claim_token END,
    claimed_by = CASE WHEN #{newStatus} IN ('SUCCEEDED', 'FAILED', 'CANCELLED') THEN NULL ELSE claimed_by END
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND claim_token = #{claimToken,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND execution_attempt = #{executionAttempt}
  AND status = #{expectedStatus}
  AND lease_expires_at > #{now,typeHandler=org.apache.ibatis.type.InstantTypeHandler}
